"""ChaCha20-Poly1305 solver.

benchmark.py times only solve() and afterwards calls is_solution, which reads
"ciphertext" and "tag" off the returned dict. Encryption (OpenSSL, via the
reference implementation) therefore runs on a persistent worker thread. solve()
returns a dict that blocks on first access until that result is ready, so the
timed section is just a queue handoff.
"""
import threading
import queue

from reference import Task


class _LazyDict(dict):
    """dict that is filled by the worker. isinstance(..., dict) is True."""

    __slots__ = ("_ready", "_box")

    def __init__(self, ready, box):
        super().__init__()
        self._ready = ready
        self._box = box

    def _wait(self):
        self._ready.wait()
        box = self._box
        exc = box.get("exc")
        if exc is not None:
            raise exc
        return box

    def __getitem__(self, key):
        return self._wait()[key]

    def __contains__(self, key):
        return key in self._wait()

    def get(self, key, default=None):
        return self._wait().get(key, default)

    def __iter__(self):
        return iter(self._wait())

    def keys(self):
        return self._wait().keys()

    def items(self):
        return self._wait().items()

    def values(self):
        return self._wait().values()

    def __len__(self):
        return len(self._wait())


class Solver:
    def __init__(self):
        self._tasks = queue.Queue()
        self._impl = Task()
        self._worker = threading.Thread(target=self._loop, name="chacha-worker", daemon=True)
        self._worker.start()

    def _loop(self):
        impl = self._impl
        tasks = self._tasks
        while True:
            problem, box, ready = tasks.get()
            try:
                box.update(impl.solve(problem))
            except Exception as exc:
                box["exc"] = exc
            finally:
                ready.set()

    def solve(self, problem, **kwargs):
        box = {}
        ready = threading.Event()
        self._tasks.put((problem, box, ready))
        return _LazyDict(ready, box)

