#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* ChaCha20 AVX2, 4 blocks at a time, using the standard quarter-round.
   We implement via compiler intrinsics. */

#include <immintrin.h>

static inline __m256i rotl32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static inline void qr(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl32(*d, 16);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl32(*b, 12);
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl32(*d, 8);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl32(*b, 7);
}

/* columns: for 4 independent blocks, each lane is one block.
   state layout per block: 16 uint32.
   We store as 16 __m256i, lane i = block i. */

static void chacha20_4blocks(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter, uint8_t *out) {
