    /* redo: 8 lanes of 32-bit = 8 blocks would be better, but we do 8 lanes = 8 blocks */
}

/* Better: 8 blocks using full 256-bit (8 x u32). */
static void chacha20_xor8(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter,
