    const uint32_t C0 = 0x61707865, C1 = 0x3320646e, C2 = 0x79622d32, C3 = 0x6b206574;
    while (bytes >= 512) {
        __m256i x0 = _mm256_set1_epi32(C0);
        __m256i x1 = _mm256_set1_epi32(C1);
        __m256i x2 = _mm256_set1_epi32(C2);
        __m256i x3 = _mm256_set1_epi32(C3);
        __m256i x4 = _mm256_set1_epi32(key[0]);
        __m256i x5 = _mm256_set1_epi32(key[1]);
        __m256i x6 = _mm256_set1_epi32(key[2]);
        __m256i x7 = _mm256_set1_epi32(key[3]);
        __m256i x8 = _mm256_set1_epi32(key[4]);
        __m256i x9 = _mm256_set1_epi32(key[5]);
        __m256i x10 = _mm256_set1_epi32(key[6]);
        __m256i x11 = _mm256_set1_epi32(key[7]);
        __m256i x12 = _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                       counter+3, counter+2, counter+1, counter);
