        x1 = _mm256_add_epi32(x1, s1);
        x2 = _mm256_add_epi32(x2, s2);
        x3 = _mm256_add_epi32(x3, s3);
        x4 = _mm256_add_epi32(x4, s4);
        x5 = _mm256_add_epi32(x5, s5);
        x6 = _mm256_add_epi32(x6, s6);
        x7 = _mm256_add_epi32(x7, s7);
        x8 = _mm256_add_epi32(x8, s8);
        x9 = _mm256_add_epi32(x9, s9);
        x10 = _mm256_add_epi32(x10, s10);
        x11 = _mm256_add_epi32(x11, s11);
        x12 = _mm256_add_epi32(x12, s12);
        x13 = _mm256_add_epi32(x13, s13);
        x14 = _mm256_add_epi32(x14, s14);
        x15 = _mm256_add_epi32(x15, s15);

        /* transpose 8 blocks of 16 words into sequential output.
           Each block is 64 bytes = 16 u32. Lanes are across blocks.
           We need to interleave so block i's words are contiguous.
           Store via extracting lanes. */
        uint32_t tmp[16][8];
        _mm256_storeu_si256((__m256i*)tmp[0], x0);
        _mm256_storeu_si256((__m256i*)tmp[1], x1);
        _mm256_storeu_si256((__m256i*)tmp[2], x2);
        _mm256_storeu_si256((__m256i*)tmp[3], x3);
        _mm256_storeu_si256((__m256i*)tmp[4], x4);
        _mm256_storeu_si256((__m256i*)tmp[5], x5);
        _mm256_storeu_si256((__m256i*)tmp[6], x6);
        _mm256_storeu_si256((__m256i*)tmp[7], x7);
        _mm256_storeu_si256((__m256i*)tmp[8], x8);
        _mm256_storeu_si256((__m256i*)tmp[9], x9);
        _mm256_storeu_si256((__m256i*)tmp[10], x10);
        _mm256_storeu_si256((__m256i*)tmp[11], x11);
        _mm256_storeu_si256((__m256i*)tmp[12], x12);
        _mm256_storeu_si256((__m256i*)tmp[13], x13);
        _mm256_storeu_si256((__m256i*)tmp[14], x14);
        _mm256_storeu_si256((__m256i*)tmp[15], x15);

