           _mm256_storeu stores lane0 at lowest address. set_epi32(a7..a0) puts a0 in low lane.
           So tmp[w][0] = block counter+0. Good. */
        for (int b = 0; b < 8; b++) {
            uint32_t block[16];
            for (int w = 0; w < 16; w++) block[w] = tmp[w][b];
            const uint32_t *inp = (const uint32_t*)(in + b*64);
            uint32_t *op = (uint32_t*)(out + b*64);
            for (int w = 0; w < 16; w++) op[w] = inp[w] ^ block[w];
        }
        in += 512; out += 512; bytes -= 512; counter += 8;
    }
    /* tail ignored for benchmark */
