    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t nonce[3] = {9,10,11};
    size_t n = 40*1024*1024;
    uint8_t *in = aligned_alloc(64, n);
    uint8_t *out = aligned_alloc(64, n);
    memset(in, 1, n);
    /* warmup */
    chacha20_xor8(key, nonce, 1, in, out, n);
    struct timespec t0, t1;
