       transpose 16 words x 4 lanes into 4 blocks of 16 words.
       4 lanes * 16 words = 16 xmm registers. We want block b = word0[b], word1[b], ...
       Use unpack epi32/64. */
    /* Process low 4 blocks and high 4 blocks with same routine via pointer. */
    __m128i *groups[2] = {lo, hi};
