    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
    uint8_t final_done;
} poly1305_ctx;

static void poly1305_init(poly1305_ctx *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
