static void poly1305_update(poly1305_ctx *st, const uint8_t *m, size_t bytes) {
    if (st->buf_used) {
        size_t want = 16 - st->buf_used;
        if (want > bytes) want = bytes;
        memcpy(st->buf + st->buf_used, m, want);
        st->buf_used += want; m += want; bytes -= want;
        if (st->buf_used == 16) {
            poly1305_blocks(st, st->buf, 16, 1);
            st->buf_used = 0;
        }
    }
    size_t n = bytes & ~((size_t)15);
    if (n) poly1305_blocks(st, m, n, 1);
    m += n; bytes -= n;
    if (bytes) {
        memcpy(st->buf, m, bytes);
        st->buf_used = bytes;
    }
