static void poly1305_final_tag(poly1305_ctx *st, uint8_t tag[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        memset(st->buf + st->buf_used + 1, 0, 16 - st->buf_used - 1);
        poly1305_blocks(st, st->buf, 16, 0);
    }
    poly1305_finish(st, tag);
}

/* RFC 8439 ChaCha20-Poly1305 (which is what OpenSSL EVP and cryptography use
   for the 12-byte nonce IETF construction). */
static void u64le(uint8_t *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (uint8_t)(v >> (8*i));
}

static void aead_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                         const uint8_t *aad, size_t aad_len,
                         const uint8_t *pt, uint8_t *ct, size_t pt_len,
                         uint8_t tag[16]) {
    uint32_t k[8], n[3];
    memcpy(k, key, 32);
    /* counter block: counter || nonce. nonce is 12 bytes little-endian words. */
    memcpy(n, nonce, 12);

    uint8_t poly_key[64];
    memset(poly_key, 0, 64);
    chacha20_xor(k, n, 0, poly_key, poly_key, 64); /* keystream block 0 */

    chacha20_xor(k, n, 1, pt, ct, pt_len);

    poly1305_ctx st;
    poly1305_init(&st, poly_key);
    poly1305_update(&st, aad, aad_len);
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    if (aad_pad) {
        uint8_t z[16] = {0};
        poly1305_update(&st, z, aad_pad);
    }
    poly1305_update(&st, ct, pt_len);
    size_t ct_pad = (16 - (pt_len & 15)) & 15;
    if (ct_pad) {
        uint8_t z[16] = {0};
        poly1305_update(&st, z, ct_pad);
    }
    uint8_t lens[16];
    u64le(lens, aad_len);
    u64le(lens+8, pt_len);
    poly1305_update(&st, lens, 16);
    poly1305_final_tag(&st, tag);
}

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad))
        return NULL;
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (aad.buf) PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce");
        return NULL;
    }
    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) {
        Py_XDECREF(ct); Py_XDECREF(tag);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (aad.buf) PyBuffer_Release(&aad);
        return NULL;
    }
    Py_BEGIN_ALLOW_THREADS
    aead_encrypt(key.buf, nonce.buf,
                 aad.buf ? aad.buf : (const uint8_t*)"", aad.buf ? (size_t)aad.len : 0,
                 pt.buf, (uint8_t*)PyBytes_AS_STRING(ct), (size_t)pt.len,
                 (uint8_t*)PyBytes_AS_STRING(tag));
    Py_END_ALLOW_THREADS
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (aad.buf) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fast_aead", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_fast_aead(void) { return PyModule_Create(&moduledef); }
