    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);
    uint32_t mask = (g4 >> 31) - 1u;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0; h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2; h3 = (h3 & mask) | g3; h4 = (h4 & mask) | g4;

    uint64_t f0 = ((uint64_t)h0 | ((uint64_t)h1 << 26)) + st->pad[0];
    uint64_t f1 = (((uint64_t)h1 >> 6) | ((uint64_t)h2 << 20)) + st->pad[1];
    uint64_t f2 = (((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14)) + st->pad[2];
    uint64_t f3 = (((uint64_t)h3 >> 18) | ((uint64_t)h4 << 8)) + st->pad[3];
    f1 += (uint32_t)(f0 >> 32);
    f2 += (uint32_t)(f1 >> 32);
    f3 += (uint32_t)(f2 >> 32);
    uint32_t o0=(uint32_t)f0, o1=(uint32_t)f1, o2=(uint32_t)f2, o3=(uint32_t)f3;
    tag[0]=o0; tag[1]=o0>>8; tag[2]=o0>>16; tag[3]=o0>>24;
    tag[4]=o1; tag[5]=o1>>8; tag[6]=o1>>16; tag[7]=o1>>24;
    tag[8]=o2; tag[9]=o2>>8; tag[10]=o2>>16; tag[11]=o2>>24;
    tag[12]=o3; tag[13]=o3>>8; tag[14]=o3>>16; tag[15]=o3>>24;
