static void poly_mac(const uint8_t key[32], const uint8_t *m, size_t n, uint8_t tag[16]) {
    poly1305_ctx st; poly1305_init(&st, key);
    size_t full = n & ~15u;
    if (full) poly1305_blocks(&st, m, full, 1u << 24);
    if (n & 15) {
        uint8_t b[16]; memset(b, 0, 16);
        memcpy(b, m+full, n&15);
        b[n&15] = 1;
        poly1305_blocks(&st, b, 16, 0);
    }
    poly1305_finish(&st, tag);
}

void Poly1305_Init(void *, const unsigned char *);
void Poly1305_Update(void *, const unsigned char *, size_t);
void Poly1305_Final(void *, unsigned char *);
size_t Poly1305_ctx_size(void);

int main() {
    uint8_t key[32], msg[64], tag1[16], tag2[16];
