        unsigned char ctx[512];
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, msg, n);
        Poly1305_Final(ctx, tag2);
        if (memcmp(tag1, tag2, 16) != 0) {
            printf("MISMATCH n=%zu\n ours ", n);
