void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

typedef struct {
    unsigned char *out, *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job;

void *run(void *p) {
    job *j = p;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

int main() {
    size_t n = 40ull*1024*1024;
    unsigned char *in = aligned_alloc(64, n);
    unsigned char *out = aligned_alloc(64, n);
    memset(in, 1, n);
    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    int nthreads = 6;
    pthread_t th[16];
    job jobs[16];
    size_t chunk = (n / nthreads) & ~63ull;
    struct timespec t0, t1;
    int reps = 5;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < reps; r++) {
        size_t off = 0;
        for (int i = 0; i < nthreads; i++) {
            size_t len = (i == nthreads-1) ? (n - off) : chunk;
            jobs[i].out = out + off;
            jobs[i].in = in + off;
