    printf("parallel %d threads: %.4f s/iter checksum %u\n", nthreads, dt/reps, out[0]+out[n/2]+out[n-1]);

    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int r = 0; r < reps; r++) {
        unsigned int ctr[4] = {1,9,10,11};
        ChaCha20_ctr32(out, in, n, key, ctr);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("serial: %.4f s/iter checksum %u\n", dt/reps, out[0]+out[n/2]+out[n-1]);
    return 0;
}
