#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

typedef unsigned __int128 u128;

static inline u128 load128(const uint8_t *p) {
    uint64_t lo, hi;
    memcpy(&lo, p, 8);
    memcpy(&hi, p+8, 8);
    return ((u128)hi << 64) | lo;
}

/* reduce 256-bit-ish value (given as 4x64, value < 2^300) mod 2^130-5, result < 2^131 */
static u128 reduce(u128 z0, u128 z1, u128 z2, u128 z3) {
    /* value = z0 + (z1<<64) + (z2<<128) + (z3<<192)
       2^130 ≡ 5.
       bits [0,130) stay; bits [130, ...) * 5.
       z0 = bits 0..63 of first limb but z0 may have high bits if we didn't mask.
       Assume z0,z1,z2,z3 are each < 2^64 (masked). */
    u128 low130 = (u128)(uint64_t)z0 | ((u128)(uint64_t)z1 << 64) | (((u128)((uint64_t)z2 & 3)) << 128);
    /* high = bits 130+ = (z2 >> 2) + (z3 << 62)  but z3<<62 needs extra room.
       high * 5 must be added. high < 2^(300-130) = 2^170. */
    u128 high_lo = ((u128)(uint64_t)z2 >> 2) | ((u128)(uint64_t)z3 << 62);
    u128 high_hi = (u128)(uint64_t)z3 >> 2; /* bits of z3 above bit 2, which are bit (192+2 - 130)=64 of high. 192-130=62, so z3's bit k is high bit 62+k. bit 64 of high = z3 bit 2. yes z3>>2. */
    /* high * 5 = high_lo*5 + (high_hi*5)<<64 */
    u128 p0 = high_lo * 5;
    u128 p1 = high_hi * 5 + (p0 >> 64);
    p0 = (uint64_t)p0;
    /* add to low130. low130 < 2^130. p0+p1<<64 < 2^170 * 5 roughly. */
    u128 sum_lo = (u128)(uint64_t)low130 + p0; /* may exceed 64? low130 low 64 + p0 */
    /* do it as 128+ */
    u128 s0 = low130 + p0;           /* p0 < 2^64, low130 < 2^130, sum < 2^131 */
    u128 s1 = (s0 < low130);         /* carry out of 128? careful, u128 wraps at 128 not 130.
                                        low130 uses bits 0..129. adding p0 (64-bit) can carry into bit 130+.
                                        Since both fit in u128 (130 < 128? NO 130 > 128). 
                                        unsigned __int128 is 128 bits. Cannot hold 130-bit low130! */
    (void)s0; (void)s1; (void)p1;
    return 0;
}

/* Represent field element as 3x64: limb0 (64), limb1 (64), limb2 (low bits). 
   Or just 5x26 which we debug. Let's use 44-bit limbs in uint64, 3 limbs cover 132 bits. */

typedef struct { uint64_t l[3]; } fe; /* each limb < 2^44 roughly, value = l0 + l1*2^44 + l2*2^88 */

static fe fe_from_block(const uint8_t b[16], int hibit) {
    uint64_t lo, hi;
    memcpy(&lo, b, 8);
    memcpy(&hi, b+8, 8);
    fe r;
    r.l[0] = lo & ((1ull<<44)-1);
    r.l[1] = (lo >> 44) | ((hi & ((1ull<<24)-1)) << 20);
    r.l[2] = (hi >> 24);
    if (hibit) r.l[2] |= 1ull << (128-88); /* bit 128, which is limb2 bit 40 */
    return r;
}

static void fe_reduce(fe *h) {
    /* partially reduce so limbs < 2^44, and fold 2^130 */
    uint64_t c;
    c = h->l[0] >> 44; h->l[0] &= (1ull<<44)-1; h->l[1] += c;
    c = h->l[1] >> 44; h->l[1] &= (1ull<<44)-1; h->l[2] += c;
    c = h->l[2] >> 42; /* 88+42 = 130 */ h->l[2] &= (1ull<<42)-1;
    h->l[0] += c * 5;
    c = h->l[0] >> 44; h->l[0] &= (1ull<<44)-1; h->l[1] += c;
    c = h->l[1] >> 44; h->l[1] &= (1ull<<44)-1; h->l[2] += c;
}

static fe fe_mul(fe a, fe b) {
    /* schoolbook, then reduce */
    __uint128_t m0 = (__uint128_t)a.l[0]*b.l[0];
    __uint128_t m1 = (__uint128_t)a.l[0]*b.l[1] + (__uint128_t)a.l[1]*b.l[0];
    __uint128_t m2 = (__uint128_t)a.l[0]*b.l[2] + (__uint128_t)a.l[1]*b.l[1] + (__uint128_t)a.l[2]*b.l[0];
    __uint128_t m3 = (__uint128_t)a.l[1]*b.l[2] + (__uint128_t)a.l[2]*b.l[1];
    __uint128_t m4 = (__uint128_t)a.l[2]*b.l[2];
    /* m_k is coefficient of 2^(44k). fold k>=3 using 2^132 = 2^(44*3) = 4 * 2^130 ≡ 20.
       2^(44*3) = 2^132 = 4 * 2^130 ≡ 20.
       2^(44*4) = 2^176 = 2^46 * 2^130 ≡ 5 * 2^46 = 5 * 2^(44+2) = 20 * 2^44.
       So m3 * 2^132 ≡ m3 * 20  added to limb0? Wait we want result limbs at 0,44,88.
       m3 contributes to position 132, which equals 20 * position 0. Yes m3*20 -> limb0, with carry.
       m4 contributes to position 176 = 44 + 132, ≡ 20 * position 44, so m4*20 -> limb1.
    */
    __uint128_t z0 = m0 + m3 * 20;
    __uint128_t z1 = m1 + m4 * 20;
    __uint128_t z2 = m2;
    /* carry propagate from 128-bit accumulators into 44-bit limbs */
    uint64_t l0 = (uint64_t)z0 & ((1ull<<44)-1);
    __uint128_t c = z0 >> 44;
    z1 += c;
    uint64_t l1 = (uint64_t)z1 & ((1ull<<44)-1);
    c = z1 >> 44;
    z2 += c;
    uint64_t l2 = (uint64_t)z2 & ((1ull<<44)-1);
    c = z2 >> 44;
    /* c is at position 132 ≡ *20 at position 0 */
    __uint128_t extra = c * 20;
    l0 += (uint64_t)extra & ((1ull<<44)-1);
    __uint128_t c2 = extra >> 44;
    l1 += (uint64_t)c2;
    uint64_t c3 = l1 >> 44; l1 &= (1ull<<44)-1; l2 += c3;
    c3 = l2 >> 44; l2 &= (1ull<<44)-1;
    /* c3 at position 132 again */
    l0 += (uint64_t)c3 * 20;
    c3 = l0 >> 44; l0 &= (1ull<<44)-1; l1 += c3;
    c3 = l1 >> 44; l1 &= (1ull<<44)-1; l2 += c3;
    fe r; r.l[0]=l0; r.l[1]=l1; r.l[2]=l2;
    return r;
}

static fe fe_add(fe a, fe b) {
    fe r;
    r.l[0]=a.l[0]+b.l[0];
    r.l[1]=a.l[1]+b.l[1];
    r.l[2]=a.l[2]+b.l[2];
    fe_reduce(&r);
    return r;
}

static void poly_mac(const uint8_t key[32], const uint8_t *m, size_t n, uint8_t tag[16]) {
    uint8_t rb[16];
    memcpy(rb, key, 16);
    rb[3] &= 15; rb[7] &= 15; rb[11] &= 15; rb[15] &= 15;
    rb[4] &= 252; rb[8] &= 252; rb[12] &= 252;
    fe r = fe_from_block(rb, 0);
    fe h = {0,0,0};
    while (n >= 16) {
        fe b = fe_from_block(m, 1);
        h = fe_add(h, b);
        h = fe_mul(h, r);
        m += 16; n -= 16;
    }
    if (n) {
        uint8_t last[16] = {0};
        memcpy(last, m, n);
        last[n] = 1;
        fe b = fe_from_block(last, 0);
        h = fe_add(h, b);
        h = fe_mul(h, r);
    }
    /* fully reduce h mod 2^130-5 */
    fe_reduce(&h);
    /* h.l[2] should be < 2^42. Compare with p = 2^130-5.
       if h >= p, subtract p. p in limbs: -5 mod 2^44 in limb0 with borrow... 
       easier convert to 130-bit and compare. */
    /* do one conditional subtract of (2^130-5) i.e. add 5 and clear bit 130 if bit 130 set or h+5 carries. */
    uint64_t l0 = h.l[0] + 5;
    uint64_t c = l0 >> 44; l0 &= (1ull<<44)-1;
    uint64_t l1 = h.l[1] + c; c = l1 >> 44; l1 &= (1ull<<44)-1;
    uint64_t l2 = h.l[2] + c;
    if (l2 >= (1ull<<42)) {
        /* h+5 >= 2^130, so h >= p, use h+5-2^130 */
        l2 &= (1ull<<42)-1;
        h.l[0]=l0; h.l[1]=l1; h.l[2]=l2;
    }
    /* add pad (128-bit) */
    fe pad = fe_from_block(key+16, 0);
    h = fe_add(h, pad);
    /* now h < 2^129, emit 16 bytes little endian. No mod. */
    uint64_t o0 = h.l[0] | (h.l[1] << 44);
    uint64_t o1 = (h.l[1] >> 20) | (h.l[2] << 24);
    memcpy(tag, &o0, 8);
    memcpy(tag+8, &o1, 8);
}

void Poly1305_Init(void *, const unsigned char *);
void Poly1305_Update(void *, const unsigned char *, size_t);
void Poly1305_Final(void *, unsigned char *);

int main() {
    uint8_t key[32], msg[256], tag1[16], tag2[16];
    for (int i = 0; i < 32; i++) key[i] = (uint8_t)(i*7+3);
    for (int i = 0; i < 256; i++) msg[i] = (uint8_t)(i*13+1);
    int bad = 0;
    for (size_t n = 0; n <= 256; n++) {
        poly_mac(key, msg, n, tag1);
        unsigned char ctx[512];
        Poly1305_Init(ctx, key);
        if (n) Poly1305_Update(ctx, msg, n);
        Poly1305_Final(ctx, tag2);
        if (memcmp(tag1, tag2, 16)) {
            printf("MISMATCH n=%zu ours ", n);
            for (int i=0;i<16;i++) printf("%02x", tag1[i]);
            printf(" ref ");
            for (int i=0;i<16;i++) printf("%02x", tag2[i]);
            printf("\n");
            bad++;
            if (bad > 5) return 1;
        }
    }
    if (!bad) printf("all match\n");
    size_t N = 4ull*1024*1024;
    uint8_t *big = malloc(N);
    memset(big, 1, N);
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    for (int i = 0; i < 3; i++) poly_mac(key, big, N, tag1);
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt = (t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("4MB x3: %.4f s/iter\n", dt/3);
    return bad?1:0;
}
